// helmrbac turns the ClusterRole generated by controller-gen into a Helm template so the chart's
// RBAC never drifts from the +kubebuilder:rbac markers in the controllers.
package main

import (
	"flag"
	"fmt"
	"os"
	"strings"

	rbacv1 "k8s.io/api/rbac/v1"
	"sigs.k8s.io/yaml"
)

const header = `# Generated by hack/helmrbac from config/rbac/role.yaml. DO NOT EDIT.
# Regenerate with: make manifests
{{- if .Values.rbac.create }}
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRole
metadata:
  name: {{ include "cloudflare-operator.fullname" . }}
  labels:
    {{- include "cloudflare-operator.labels" . | nindent 4 }}
`

func main() {
	in := flag.String("in", "config/rbac/role.yaml", "controller-gen ClusterRole")
	out := flag.String("out", "charts/cloudflare-operator/templates/clusterrole.yaml", "Helm template to write")
	flag.Parse()

	raw, err := os.ReadFile(*in)
	if err != nil {
		fail(err)
	}
	var role rbacv1.ClusterRole
	if err := yaml.Unmarshal(raw, &role); err != nil {
		fail(fmt.Errorf("parse %s: %w", *in, err))
	}
	rules, err := yaml.Marshal(map[string]any{"rules": role.Rules})
	if err != nil {
		fail(err)
	}
	var b strings.Builder
	b.WriteString(header)
	b.Write(rules)
	b.WriteString("{{- end }}\n")
	if err := os.WriteFile(*out, []byte(b.String()), 0o644); err != nil {
		fail(err)
	}
}

func fail(err error) {
	fmt.Fprintln(os.Stderr, "helmrbac:", err)
	os.Exit(1)
}
